import{d as t,S as d,i as o,l as a}from"./chunks/framework.CY2TYXqZ.js";const f=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/index.md","filePath":"zh-TW/guide/index.md"}'),r={name:"zh-TW/guide/index.md"};function l(i,e,c,h,n,s){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to “快速上手”">​</a></h1><p>教師研習與共用電腦使用，請先看<a href="./workshop">開始、保存與離開</a>。</p><h2 id="平台介紹" tabindex="-1">平台介紹 <a class="header-anchor" href="#平台介紹" aria-label="Permalink to “平台介紹”">​</a></h2><p>Web eXploitation Laboratory（WXL）是給學習者使用的 Web 資安挑戰平台。題目本身、你用來攻擊它的工具、以及對答案的比對，全部都在你自己的瀏覽器分頁裡執行。</p><ul><li>開啟題目頁時會下載該題專屬的 <code>runtime.wasm</code>，題目應用程式的程式碼與檔案都封裝在裡面。</li><li>你送出的 flag 是在瀏覽器內的那個 WASM 模組裡比對的，不會送到任何伺服器。</li><li>你的筆記、攻擊紀錄、Code 草稿與你解出過哪些題目，只寫進這台瀏覽器的 IndexedDB 資料庫 <code>challenge-tools</code>，不會上傳；把這個網站的瀏覽器資料清掉，這些內容就一起消失且無法救回。</li><li>進站時網站會註冊一支名為 <code>challenge-sw.js</code> 的 Service Worker，它是題目網址能被瀏覽器攔下來的前提。它只接管 <code>challenge-&lt;題目 slug&gt;.localhost</code> 形式的主機名稱，其餘請求一律直接放行，也不做任何離線快取。</li></ul><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to “系統需求”">​</a></h2><table tabindex="0"><thead><tr><th>需求項目</th><th>為什麼需要</th></tr></thead><tbody><tr><td>能執行 WebAssembly 的瀏覽器</td><td>每個題目頁都會抓取一份 <code>runtime.wasm</code> 並在分頁內執行。</td></tr><tr><td>允許本站註冊 Service Worker</td><td>進站時會註冊 <code>challenge-sw.js</code>。沒有它，送往 <code>challenge-&lt;題目 slug&gt;.localhost</code> 的請求不會被攔截。</td></tr><tr><td>解題全程都要有網路連線</td><td>Python 執行環境是從外部 CDN 的 <code>https://cdn.jsdelivr.net/pyodide/v0.29.3/full/pyodide.js</code> 載入的。完全離線時 Python 題目跑不起來。首次載入需要下載數十 MB。</td></tr><tr><td>瀏覽器儲存空間（IndexedDB）可用</td><td>攻擊紀錄、筆記、Code 草稿與解題進度保存在本機。儲存警告出現時，先下載可取得的紀錄並另外保存未儲存文字，再依提示處理。</td></tr><tr><td>桌機寬度的螢幕</td><td>Browser 面板的上一頁、下一頁、重新載入三顆鈕只在桌機寬度才會出現；手機寬度整組隱藏，只留下網址列與 Go。</td></tr></tbody></table><p>Service Worker 註冊與 Pyodide 下載是最常讓面板卡住的兩件事。面板按不動、輸出遲遲不出現、筆記存不起來時，請看<a href="./troubleshooting">疑難排解</a>。</p><h2 id="快速開始步驟" tabindex="-1">快速開始步驟 <a class="header-anchor" href="#快速開始步驟" aria-label="Permalink to “快速開始步驟”">​</a></h2><h3 id="步驟一-選題" tabindex="-1">步驟一：選題 <a class="header-anchor" href="#步驟一-選題" aria-label="Permalink to “步驟一：選題”">​</a></h3><ol><li>打開題目清單。每一列會顯示補到三位數的永久編號（例如 <code>#003</code>）、標題、難度徽章、類別徽章與日期，第二行是描述與標籤。只有英文版的題目，標題與描述是英文，並帶著語系標記「只有英文」。</li><li>用工具列篩選。搜尋框只比對標題、描述與標籤三個欄位，打進難度或日期文字不會有結果。停止打字 300 毫秒後清單才會更新。</li><li>難度下拉選單是固定的四個英文選項：Easy、Medium、Hard、Mystery。類別下拉選單則由清單裡實際出現過的類別動態產生。難度徽章直接印出 frontmatter 的原始字串，中英文介面底下都是英文小寫。</li><li>工具列右側的數字是目前篩選後剩下幾道題。右上角的按鈕可在預設的列表模式與格線模式之間切換。</li><li>點一列即可進入該題。</li></ol><p><code>#NNN</code> 是題目的永久編號，由出題者指派一次。中英文兩份清單顯示同一個號碼，新增題目或改名題目資料夾都不會讓它位移，可以放心用它來指稱一道有永久編號的題目。還沒有永久編號的題目會顯示暫時的號碼，它不是永久編號，可能改變，也可能和別題的號碼重複，不要用它指稱題目。</p><h3 id="步驟二-在面板裡解題" tabindex="-1">步驟二：在面板裡解題 <a class="header-anchor" href="#步驟二-在面板裡解題" aria-label="Permalink to “步驟二：在面板裡解題”">​</a></h3><ol><li>題目頁開啟時停在 Browser 分頁。分頁列預設有四個：Browser、Network、Repeater、Code，這些名稱在中英文介面底下都是寫死的英文。</li><li>出題者可以限制提供哪些工具分頁，但 Browser 分頁一定保留，永遠不會消失。</li><li>Browser 面板的網址列預先填好該題專屬的 <code>https://challenge-&lt;題目 slug&gt;.localhost/</code>。它是一個可自由編輯的文字輸入框，按 Enter 或點 Go 就會導覽。</li><li>注意導覽列右上角的狀態燈：閃動的黃點表示執行環境還在載入，綠點表示就緒，紅點表示失敗——把滑鼠移到紅點上可以看到實際的錯誤訊息。</li><li>Code 分頁的 Python 執行環境要等你第一次點開該分頁才開始下載，不是進題目頁就下載，所以第一次切過去會等一段時間。</li></ol><h3 id="步驟三-提交-flag" tabindex="-1">步驟三：提交 flag <a class="header-anchor" href="#步驟三-提交-flag" aria-label="Permalink to “步驟三：提交 flag”">​</a></h3><ol><li>等待執行環境就緒，並先完成沿用／清除的選擇，再貼入旗標並按「送出旗標」。</li><li>驗證與保存期間會停用提交，兩個入口共用處理中狀態。</li><li>答案判定與儲存結果分開顯示。答對但未完整儲存時，先匯出能取得的內容；重送會算另一次提交。</li><li>目前無法驗證不等於答錯，請待執行環境就緒後重試。</li><li>攻擊紀錄建立後，未解出也能下載；已解出才提供滲透筆記下載入口。匯出選項與限制見<a href="./notes#匯出">筆記</a>。</li></ol><p>收合題目說明後，底部仍有交旗入口。已儲存的解題進度在沿用後顯示；讀取失敗有提示與重試，不會宣稱零完成。</p><h2 id="工具面板總覽" tabindex="-1">工具面板總覽 <a class="header-anchor" href="#工具面板總覽" aria-label="Permalink to “工具面板總覽”">​</a></h2><table tabindex="0"><thead><tr><th>面板</th><th>位置</th><th>提供什麼</th></tr></thead><tbody><tr><td>Code Editor</td><td><code>Code</code> 分頁</td><td>上方是 Python 編輯器、下方是輸出區，一開啟時高度比例為 65 / 35，中間有一條可拖曳的分隔線。含 Run 與 Stop 按鈕、每題各自的執行歷史紀錄，以及可調整自動完成、括號自動閉合與字型大小的設定浮層。見 <a href="./python">Python Code Editor</a>。</td></tr><tr><td>Browser</td><td><code>Browser</code> 分頁</td><td>預先填好、可自由改寫的網址列，底下是渲染出來的回應；桌機寬度另有上一頁、下一頁與重新載入三顆鈕。上一頁與下一頁只是把先前存下來的畫面搬回來，不會重新發出請求。見 <a href="./browser">Browser 面板</a>。</td></tr><tr><td>Network Traffic</td><td><code>Network</code> 分頁</td><td>標題固定寫著 <code>Network Traffic</code>，旁邊顯示目前記錄筆數；表格有五欄 <code>#</code>、<code>Method</code>、<code>URL</code>、<code>Status</code>、<code>Time</code>，工具列右側有一顆 <code>Clear</code>。Browser 面板、Repeater 與 Code Editor 發出的請求都會進同一份記錄，沒有任何一個面板被排除。見 <a href="./network">Network 與 Repeater</a>。</td></tr><tr><td>Repeater</td><td><code>Repeater</code> 分頁</td><td>一整塊可自由改寫的 <code>Raw HTTP Request</code> 純文字編輯區，預先填好一份 Host 為 <code>challenge-&lt;題目 slug&gt;.localhost</code> 的 <code>GET /</code> 請求，右側是已存 snapshot 的側欄，另有 Send 按鈕。在 Network 記錄展開某一列時會出現 <code>Send to Repeater</code>，按下會切到這個分頁並覆蓋編輯區原本的內容。見 <a href="./network">Network 與 Repeater</a>。</td></tr><tr><td>Pentest Notes</td><td>導覽列按鈕，點了才開啟面板</td><td>每題各自獨立的筆記，含 Markdown 預覽、搜尋框，以及新→舊／舊→新的排序切換。該題至少有一篇筆記時，按鈕上才會出現數字徽章。編輯區的文字只有在按下「儲存」的那一刻才會被存下來。見 <a href="./notes">滲透筆記</a>。</td></tr></tbody></table><p>Network 的流量記錄只活在你目前這個頁面上，換頁之後會整份清空；這一頁有另一個語系的版本時，切換語系會前往那個版本，記錄也會清空。</p>',20)])])}const b=t(r,[["render",l]]);export{f as __pageData,b as default};
